/* 移除顶部菜单栏下方的阴影线 */
.nav-menu-bar,
#top-nav,
#top-bar,
.nav-header,
.icon-menu-bar,
#icon-bar {
    box-shadow: none !important;
    border-bottom: none !important;
}

/* 新增装饰层，菜单栏花边 */
.nav-menu-bar::after,
#top-nav::after,
#top-bar::after {
    content: '';
    position: absolute;
    background-repeat: no-repeat;
    z-index: -1;
    opacity: 1;
    pointer-events: none;
    /* 不影响交互 */
}

/* 移动端适配 */
@media (max-width: 768px) {

    .nav-menu-bar::after,
    #top-nav::after {
        height: 18px;
        /* 缩小高度适应移动端 */
        background-size: cover;
        /* 保持图片比例 */
    }
}

/* 按钮样式 - 添加最少样式以确保伪元素显示 */
.swipe_left,
.swipe_right {
    display: inline-flex !important;
    /* 使用 inline-flex 确保伪元素可居中显示 */
    width: 40px !important;
    /* 按钮宽度，确保伪元素有足够空间 */
    height: 40px !important;
    /* 按钮高度，确保图片和偏移量有空间 */
    font-size: 0 !important;
    /* 隐藏原始文本或图标 */
    color: transparent !important;
    /* 确保文本不可见 */
    opacity: 1 !important;
    /* 确保按钮常亮 */
    filter: none !important;
    /* 移除滤镜，确保无遮罩 */
}

/* 隐藏所有浏览器滚动条 */

/* 保留滚动功能 */
#chat,
.mes_block,
#send_textarea,
.drawer-content,
.settings-panel {
    overflow-y: auto;
    /* 允许垂直滚动 */
    overflow-x: hidden;
    /* 禁止水平滚动 */
}

/* ===== 底部输入框区域：4px外边框 + 4px间隔效果 ===== */
#nonQRFormItems {
    background-color: #B7C399 !important; /* 底框颜色 */

    /* 核心属性：4px 外边框 */
    outline: 4px solid #B7C399 !important; 

    /* 核心属性：外边框与底框之间的 4px 间隔 */
    /* 这里的间隔会透出你下层的背景图或聊天区域背景 */
    outline-offset: 4px !important;

    /* --- 布局优化方案 --- */
    /* 1. 因为轮廓（outline）向外延伸，需要给容器预留空间防止溢出屏幕 */
    margin: 12px auto !important; 
    width: calc(100% - 24px) !important; 

    /* 2. 建议加上细微圆角，否则方角在大偏移量下会显得生硬 */
    border-radius: 4px !important;

    /* 3. 去掉可能存在的原生边框 */
    border: none !important;

    /* 4. 提升层级，确保边框显示在最前端 */
    z-index: 10;
}

/* 内部输入文本框微调，确保文字在 #B7C399 背景上清晰 */
#send_textarea {
    background-color: rgba(255, 255, 255, 0.4) !important;
    color: #333 !important; /* 根据深浅调整文字颜色 */
    border: none !important;
}
